new = 'from stepnx.authoring.noteskin import LocalNoteskinPack, PngAtlas, hold_atlas_plan\n'
assert old in text
text = text.replace(old, new, 1)

old = '        self._noteskin_pack: LocalNoteskinPack | None = None\n        self._pixmaps: dict[str, QPixmap] = {}\n'
new = '        self._noteskin_pack: LocalNoteskinPack | None = None\n        self._pixmaps: dict[str, QPixmap] = {}\n        self._hold_terminal_pixmaps: dict[tuple[str, int, int, bool], QPixmap] = {}\n'
assert old in text
text = text.replace(old, new, 1)

old = '        self._noteskin_pack = pack\n        self._pixmaps.clear()\n'
